mapper.update:
UPDATE room
room_number = #{roomNumber}, type_name = #{typeName}, price = #{price}, status = #{status}, img1 = #{img1}, img2 = #{img2}, img3 = #{img3},
WHERE id = #{id}

mapper.select:
SELECT * FROM room
WHERE hotel_id = #{hotelId}

    AND type_name = #{typeName}

ORDER BY room_number ASC

SELECT * FROM room
WHERE hotel_id = #{hotelId}
  AND type_name = #{typeName}
  AND status = 1
  AND id NOT IN (
    SELECT room_id FROM hotel_order
    WHERE status IN (1, 2) -- 正在预约或已入住的均视为占用
      AND NOT (start_date >= #{endDate} OR end_date <= #{startDate})
)
    LIMIT 1
